'use strict';
/* SF Symbols REALES renderizados en macOS (mismos glifos que la app, pixel-perfect) */
/* SF Symbols REALES de Apple (los mismos glifos que usa la app), renderizados a PNG x3.
   GBOX = caja natural de cada glifo en PUNTOS de la app -> el demo la escala por UI_SCALE
   (ancho de pantalla del demo / ancho del iPhone) y queda 1:1 con la app. */
const GLYPH = {flash15:"data:image/png;base64,",flashon15:"data:image/png;base64,",flashoff15:"data:image/png;base64,",live15:"data:image/png;base64,",liveslash15:"data:image/png;base64,",gallery17:"data:image/png;base64,",flip18:"data:image/png;base64,",flash24:"data:image/png;base64,",liveslash25:"data:image/png;base64,",timer25:"data:image/png;base64,",plusminus25:"data:image/png;base64,",role25:"data:image/png;base64,",moon30:"data:image/png;base64,",viewfinder30:"data:image/png;base64,",lockopen25:"data:image/png;base64,",lockfill12:"data:image/png;base64,"};
const GBOX = {flash15:[18.00,22.00],flashon15:[15.00,21.00],flashoff15:[15.00,21.00],live15:[20.00,20.00],liveslash15:[19.00,20.00],gallery17:[25.00,19.00],flip18:[22.00,20.00],flash24:[28.00,34.00],liveslash25:[32.00,31.00],timer25:[29.00,28.00],plusminus25:[21.00,24.00],role25:[30.00,32.00],moon30:[35.00,35.00],viewfinder30:[36.00,34.00],lockopen25:[32.00,27.00],lockfill12:[12.00,14.00]};
/* ═══════════ CONFIG — the only deploy-time switches ═══════════ */
const CONFIG = {
  appStoreUrl: 'https://apps.apple.com/app/id6762047518',
  contactEmail: 'support@myellelab.com'   // monitored mailbox (same as in-app)
};

/* ═══════════ SITE PLUMBING ═══════════ */
const $  = (s, r=document) => r.querySelector(s);
const $$ = (s, r=document) => [...r.querySelectorAll(s)];
const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;

// scroll progress
addEventListener('scroll', () => {
  const h = document.documentElement;
  const p = h.scrollTop / (h.scrollHeight - h.clientHeight || 1);
  $('#progress').style.width = (p * 100) + '%';
}, { passive: true });

// mobile menu
const menuBtn = $('#menuBtn'), navLinks = $('#navLinks');
menuBtn.addEventListener('click', () => {
  const open = navLinks.classList.toggle('open');
  menuBtn.setAttribute('aria-expanded', open);
});
navLinks.addEventListener('click', e => {
  if (e.target.closest('a')) { navLinks.classList.remove('open'); menuBtn.setAttribute('aria-expanded','false'); }
});

// reveal on scroll
const io = new IntersectionObserver(es => es.forEach(e => {
  if (e.isIntersecting) { e.target.classList.add('in'); io.unobserve(e.target); }
}), { threshold: .14 });
$$('.rv').forEach(el => io.observe(el));

// contact email from CONFIG
const mail = $('#mailLink');
mail.href = 'mailto:' + CONFIG.contactEmail;
mail.textContent = CONFIG.contactEmail;

/* every "Get MyTwinLens" CTA points at the live App Store listing */
$$('.cta-store').forEach(a => { a.href = CONFIG.appStoreUrl; a.removeAttribute('data-scroll'); });

/* ═══════════ DEMO ENGINE — replica 1:1 de la UI de MyTwinLens v1.9.16 ═══════════ */
(() => {
  const MODES = [['TIME-LAPSE','timelapse'],['SLO-MO','slomo'],['VIDEO','video'],['PHOTO','photo'],['INTERVAL','interval']];
  const GAP = 21.8;                     // 26pt entre bordes de labels (ModeCarousel v1.8.10) x UI_SCALE

  /* ── 1:1 con la app ──
     La pantalla del demo mide 330px y el iPhone de la app 393pt: todo lo que la app
     define en puntos se pinta aca multiplicado por UI_SCALE. Los iconos NO se dibujan
     a mano: son los SF Symbols reales de Apple (GLYPH), usados como mascara para que
     tomen el color del CSS igual que foregroundStyle en SwiftUI. */
  const UI_SCALE = 330 / 393;
  function paintGlyphs(root = document) {
    $$('[data-g]', root).forEach(el => {
      const k = el.dataset.g, box = GBOX[k];
      if (!box || el.dataset.painted) return;
      const s = +(el.dataset.gs || 1);
      if (!el.style.width)  el.style.width  = (box[0] * UI_SCALE * s).toFixed(2) + 'px';
      if (!el.style.height) el.style.height = (box[1] * UI_SCALE * s).toFixed(2) + 'px';
      const u = 'url("' + GLYPH[k] + '")';
      el.style.webkitMaskImage = u; el.style.maskImage = u;
      el.dataset.painted = '1';
    });
  }

  /* aro del time-lapse: reloj de 60 posiciones — 6 LARGAS (cada 60°) + 9 cortitas entre
     cada par, TODAS con la punta exterior en r=40 (aire entre el aro y el disco rojo).
     Coordenadas en PUNTOS de la app: el viewBox 80x80 se escala solo. (RecordButton, v1.9.16) */
  function timeLapseTicks(svg) {
    let s = '';
    for (let i = 0; i < 60; i++) {
      const major = i % 10 === 0;
      const h = major ? 6.5 : 2.4, w = major ? 1.9 : 1.4;
      s += '<rect x="' + (40 - w / 2).toFixed(2) + '" y="0" width="' + w + '" height="' + h +
           '" rx="' + (w / 2) + '" fill="rgba(255,255,255,' + (major ? .95 : .85) + ')"' +
           ' transform="rotate(' + (i * 6) + ' 40 40)"/>';
    }
    svg.innerHTML = s;
  }
  $$('.ringsvg.rt').forEach(timeLapseTicks);
  const state = {
    mode: 'photo', zoom: 1, ev: 0, flashMode: 'auto', live: false, night: false,
    front: false, recording: false, recSec: 0, countdown: null, t: 0
  };
  const phones = [$('#phLens'), $('#phMirror')].map(root => ({
    root,
    canvas: $('canvas', root), ctx: $('canvas', root).getContext('2d'),
    vf: $('.vf', root), blink: $('.blink', root), cd: $('.cd', root),
    reticle: $('.reticle', root), recpill: $('.recpill', root), rt: $('.rt', root),
    cfgpill: $('.cfgpill', root),
    zoompills: $('.zoompills', root), carousel: $('.carousel', root),
    caps: $('.caps', root), strip: $('.strip', root),
    gallery: $('.gallery', root), shutter: $('.shutter', root)
  }));
  const [lens, mirror] = phones;

  /* layout: zoom pills + carousel labels */
  const ZOOMS = [0.5, 1, 2, 3];
  phones.forEach(p => {
    ZOOMS.forEach(z => {
      const b = document.createElement(p.zoompills.dataset.live ? 'button' : 'span');
      b.className = 'zp'; b.dataset.z = z;
      if (p.zoompills.dataset.live) { b.setAttribute('aria-label', 'Zoom ' + z + 'x'); b.addEventListener('click', () => setZoom(z, true)); }
      p.zoompills.appendChild(b);
    });
    MODES.forEach(([label, id]) => {
      const el = document.createElement(p.carousel.dataset.live ? 'button' : 'span');
      el.className = 'm'; el.textContent = label; el.dataset.id = id;
      if (p.carousel.dataset.live) {
        el.setAttribute('role', 'tab');
        el.addEventListener('click', () => { if (!state.recording) setMode(id); });
      }
      p.strip.appendChild(el);
    });
    // position pills/carousel inside the phone (kept in sync on resize)
    const place = () => {
      const vfR = p.vf.getBoundingClientRect(), phR = p.root.getBoundingClientRect();
      const u = phR.width / 393;                    // 1 punto de la app, en px
      p.zoompills.style.top = (vfR.bottom - phR.top - 40 * u) + 'px';   // 40pt sobre el borde del visor
    };
    new ResizeObserver(place).observe(p.root); requestAnimationFrame(place);
  });

  /* carousel geometry (measured widths + fixed gap, like the app) */
  function carouselLayout(p, dragOffset = 0, animate = true) {
    const ms = $$('.m', p.strip);
    const widths = ms.map(m => m.getBoundingClientRect().width);
    const idx = MODES.findIndex(([, id]) => id === state.mode);
    const centers = []; let x = 0;
    widths.forEach((w, i) => { centers.push(x + w / 2); x += w + GAP; });
    const total = x - GAP;
    const shift = -centers[idx] + dragOffset;
    p.strip.style.transition = animate && !reduced ? '' : 'none';
    p.strip.style.transform = 'translateX(' + shift + 'px)';
    p.caps.style.width = (widths[idx] + 26) + 'px';
    ms.forEach((m, i) => {
      m.classList.toggle('on', i === idx);
      if (m.tagName === 'BUTTON') m.setAttribute('aria-selected', i === idx);
    });
    return { centers, idx, widths };
  }

  /* drag del carrusel — en LOS DOS telefonos (en la app cualquiera de los dos manda).
     El drag arranca a los 8px, como la app: capturar en pointerdown se tragaba los CLICKS. */
  function attachCarouselDrag(p) {
    const mc = p.carousel;
    let dragX = null, geo = null, dragging = false;
    mc.addEventListener('pointerdown', e => {
      if (state.recording) return;
      dragX = e.clientX; dragging = false;
      geo = carouselLayout(p, 0, false);
    });
    mc.addEventListener('pointermove', e => {
      if (dragX === null) return;
      let d = e.clientX - dragX;
      if (!dragging && Math.abs(d) > 8) {
        dragging = true;
        mc.setPointerCapture(e.pointerId);
        p.strip.classList.add('drag');
      }
      if (!dragging) return;
      const pos = geo.centers[geo.idx] - d;
      const first = geo.centers[0], last = geo.centers[geo.centers.length - 1];
      if (pos < first) d = geo.centers[geo.idx] - (first + (pos - first) / 3);
      if (pos > last)  d = geo.centers[geo.idx] - (last  + (pos - last)  / 3);
      carouselLayout(p, d, false);
    });
    const endDrag = e => {
      if (dragX === null) return;
      const d = e.clientX - dragX; dragX = null;
      if (!dragging) return;                  // fue un tap: lo maneja el click del label
      dragging = false;
      p.strip.classList.remove('drag');
      const target = geo.centers[geo.idx] - d;
      let best = 0, bd = 1e9;
      geo.centers.forEach((c, i) => { const dd = Math.abs(c - target); if (dd < bd) { bd = dd; best = i; } });
      if (MODES[best][1] === state.mode) carouselLayout(p);       // rebote al centro
      else setMode(MODES[best][1]);
    };
    mc.addEventListener('pointerup', endDrag);
    mc.addEventListener('pointercancel', endDrag);
  }
  phones.forEach(attachCarouselDrag);

  /* state transitions — el estado es UNO SOLO y los dos telefonos lo reflejan igual */
  function setMode(id) {
    if (state.mode === id) return;
    state.mode = id;
    phones.forEach(p => {
      carouselLayout(p);
      p.shutter.classList.toggle('video', id === 'video');
      p.shutter.classList.toggle('slomo', id === 'slomo');
      p.shutter.classList.toggle('tl', id === 'timelapse');
      const red = ['video','slomo','timelapse'].includes(id);
      $('.core', p.shutter).style.background = red ? '#ff3b30' : '';
      // SHOTS/EVERY/AF y el resumen 10/3s solo existen en INTERVAL, como en la app
      p.drawer?.classList.toggle('interval', id === 'interval');
      p.cfgpill.classList.toggle('on', id === 'interval');
    });
  }
  function setZoom(z, snap) {
    state.zoom = Math.min(3, Math.max(0.5, +z));
    phones.forEach(p => $$('.zp', p.zoompills).forEach(b => {
      const on = Math.abs(+b.dataset.z - nearestZoom()) < .01;
      b.classList.toggle('on', on);
      b.textContent = on ? fmtZoom(state.zoom) + 'x' : (+b.dataset.z < 1 ? '0,5' : b.dataset.z);
    }));
  }
  const nearestZoom = () => ZOOMS.reduce((a, b) => Math.abs(b - state.zoom) < Math.abs(a - state.zoom) ? b : a);
  const fmtZoom = z => (Math.round(z * 10) / 10).toString().replace('.', ',').replace(/,0$/, '');

  /* ── FLASH y LIVE: mismo comportamiento que en la app ──
     FLASH cicla auto -> on -> off (FlashGlyph: bolt.badge.a.fill blanco / bolt.fill AMARILLO /
     bolt.slash.fill blanco) y LIVE alterna livephoto AMARILLO / livephoto.slash blanco.
     Cada cambio dispara el ToastPill ("FLASH ON", "LIVE OFF"...), amarillo si queda encendido.
     No tocan la imagen del demo — pero se ven y se animan exactamente como los originales. */
  const FLASH_GLYPH = { auto: 'flash15', on: 'flashon15', off: 'flashoff15' };
  const nextFlash   = { auto: 'on', on: 'off', off: 'auto' };

  function setGlyph(el, key) {                     // cambia el SF Symbol y su caja, con crossfade
    const box = GBOX[key]; if (!box) return;
    el.dataset.g = key;
    el.style.width  = (box[0] * UI_SCALE).toFixed(2) + 'px';
    el.style.height = (box[1] * UI_SCALE).toFixed(2) + 'px';
    const u = 'url("' + GLYPH[key] + '")';
    el.style.webkitMaskImage = u; el.style.maskImage = u;
    el.animate?.([{ opacity: 0 }, { opacity: 1 }], { duration: 180, easing: 'ease-out' });
  }

  let toastT = null;
  function showToast(text, yellow) {               // ambos roles ven el mismo toast (estado unico)
    clearTimeout(toastT);
    phones.forEach(p => {
      const t = $('.toast', p.root);
      t.textContent = text;
      t.classList.add('on');
      t.classList.toggle('yl', yellow);
      t.animate?.([{ opacity: 0, transform: 'translate(-50%,-50%) scale(.92)' },
                   { opacity: 1, transform: 'translate(-50%,-50%) scale(1)' }],
                  { duration: 180, easing: 'ease-out' });
    });
    toastT = setTimeout(() => phones.forEach(p => $('.toast', p.root).classList.remove('on')), 1600);
  }

  function cycleFlash() {
    state.flashMode = nextFlash[state.flashMode];
    const on = state.flashMode === 'on';
    $$('[data-ctl="flash"]').forEach(c => {
      setGlyph($('.gg', c), FLASH_GLYPH[state.flashMode]);
      c.classList.toggle('on', on);                // amarillo solo en ON, como FlashGlyph
      c.setAttribute('aria-pressed', on);
    });
    showToast('FLASH ' + state.flashMode.toUpperCase(), state.flashMode !== 'off');
  }
  function toggleLive() {
    state.live = !state.live;
    $$('[data-ctl="live"]').forEach(c => {
      setGlyph($('.gg', c), state.live ? 'live15' : 'liveslash15');
      c.classList.toggle('on', state.live);
      c.setAttribute('aria-pressed', state.live);
    });
    showToast(state.live ? 'LIVE' : 'LIVE OFF', state.live);
  }
  $$('[data-ctl="flash"]').forEach(b => b.addEventListener('click', cycleFlash));
  $$('[data-ctl="live"]').forEach(b => b.addEventListener('click', toggleLive));

  /* toda herramienta BLOQUEADA del demo (el flip a camara frontal incluido) hace lo mismo:
     abre el cajon en los dos telefonos y destella el CTA — se ve entera, se usa en la app */
  function unlockHint() {
    phones.forEach(p => {
      p.drawer.classList.add('open');
      const b = $('[data-ctl="drawer"]', p.root);
      b.classList.add('on'); b.setAttribute('aria-expanded', 'true');
      $('.dcta', p.drawer)?.animate?.(
        [{ transform: 'scale(1)' }, { transform: 'scale(1.06)' }, { transform: 'scale(1)' }],
        { duration: 300, easing: 'ease-out' });
    });
  }
  $$('[data-ctl="flip"]').forEach(b => b.addEventListener('click', e => { e.stopPropagation(); unlockHint(); }));

  /* tap to focus: en CUALQUIERA de los dos telefonos → reticula en los DOS, mismo punto */
  let retTimer = null;
  $$('[data-tapfocus]').forEach(vf => vf.addEventListener('pointerdown', e => {
    if (e.target.closest('button')) return;
    const r = vf.getBoundingClientRect();
    showReticle((e.clientX - r.left) / r.width, (e.clientY - r.top) / r.height);
  }));
  function showReticle(nx, ny) {
    phones.forEach(p => {
      const r = p.reticle;
      r.style.display = 'block';
      r.style.left = 'calc(' + (nx * 100) + '% - 37px)';
      r.style.top  = 'calc(' + (ny * 100) + '% - 37px)';
      r.animate?.([{ transform: 'scale(1.25)', opacity: .4 }, { transform: 'scale(1)', opacity: 1 }], { duration: 160, easing: 'ease-out' });
    });
    clearTimeout(retTimer);
    retTimer = setTimeout(() => phones.forEach(p => p.reticle.style.display = 'none'), 1600);
  }

  /* shutter — blink 40/60/120ms on BOTH screens (v1.8.12), then capture */
  function blinkBoth() {
    phones.forEach(p => {
      const b = p.blink;
      b.animate?.([
        { opacity: 0 }, { opacity: .6, offset: .18 }, { opacity: .6, offset: .45 }, { opacity: 0 }
      ], { duration: 220, easing: 'ease-out' });
    });
  }
  function capturePhoto() {
    blinkBoth();
    if (state.flashMode === 'on' && !state.night) flashScene();
    setTimeout(() => {
      // gallery circle: snapshot of the Lens frame, both devices save (demo default ON)
      phones.forEach(p => {
        let c = p.gallery.querySelector('canvas');
        if (!c) { p.gallery.innerHTML = ''; c = document.createElement('canvas'); c.width = 88; c.height = 88; p.gallery.appendChild(c); }
        const g = c.getContext('2d');
        const src = lens.canvas;
        const s = Math.min(src.width, src.height);
        g.drawImage(src, (src.width - s) / 2, (src.height - s) / 2, s, s, 0, 0, 88, 88);
        p.gallery.classList.remove('pop'); void p.gallery.offsetWidth; p.gallery.classList.add('pop');
      });
    }, 130);
  }
  let flashT = 0;
  function flashScene() { flashT = state.t; }

  /* interval mode: mini burst — 5 shots, one every 1.5s, stop on tap (like the app) */
  let burstT = null, burstTaken = 0, burstOn = false;
  function toggleDemoBurst() {
    burstOn = !burstOn;
    phones.forEach(p => {
      p.recpill.style.display = burstOn ? 'flex' : 'none';
      // v1.9.17: la pill de rafaga es SOLO el contador (tomadas/elegidas) — sin punto ni intervalo
      $('.rr', p.recpill).style.display = burstOn ? 'none' : '';
      p.shutter.classList.toggle('bon', burstOn);
      p.cfgpill.classList.toggle('on', !burstOn);   // corriendo, el progreso ocupa su lugar
    });
    if (!burstOn) { clearTimeout(burstT); return; }
    burstTaken = 0;
    const shot = () => {
      if (!burstOn) return;
      capturePhoto(); burstTaken++;
      phones.forEach(p => p.rt.textContent = burstTaken + '/5');
      if (burstTaken >= 5) {
        burstOn = false;
        setTimeout(() => phones.forEach(p => {
          p.recpill.style.display = 'none';
          p.shutter.classList.remove('bon');
          p.cfgpill.classList.toggle('on', state.mode === 'interval');
        }), 900);
        return;
      }
      burstT = setTimeout(shot, 1500);
    };
    shot();
  }
  function fireShutter() {
    if (state.countdown !== null) return;
    if (state.mode === 'interval') { toggleDemoBurst(); return; }
    if (state.mode === 'photo') { capturePhoto(); return; }
    // video-family modes → toggle recording
    state.recording = !state.recording;
    phones.forEach(p => {
      p.shutter.classList.toggle('rec', state.recording);
      p.recpill.style.display = state.recording ? 'flex' : 'none';
      $('.rr', p.recpill).style.display = '';        // video: punto rojo + tiempo
      $('.rr', p.recpill).style.background = '#ff3b30';
    });
    if (state.recording) { state.recSec = 0; tickRec(); }
    else { clearTimeout(recT); capturePhoto(); } // stop → poster frame lands in the gallery (v1.8.11)
  }
  let recT = null;
  function tickRec() {
    phones.forEach(p => p.rt.textContent = String(Math.floor(state.recSec / 60)).padStart(2, '0') + ':' + String(state.recSec % 60).padStart(2, '0'));
    if (!state.recording) return;
    recT = setTimeout(() => { state.recSec++; tickRec(); }, 1000);
  }
  $$('[data-ctl="shutter"]').forEach(b => b.addEventListener('click', fireShutter));

  /* ── DRAWER: replica del drawerSheet de la app, con los MISMOS SF Symbols.
     SHOTS / EVERY / AF solo existen en modo INTERVAL (igual que en la app) y ASPECT va
     solo en su fila. Todo con candado (unavailable): se ve entero, se usa en la app. ── */
  const DRAWER_ITEMS = [
    ['FLASH',      '<i class="gg" data-g="flash24"></i>',      false],
    ['LIVE',       '<i class="gg" data-g="liveslash25"></i>',  false],
    ['TIMER',      '<i class="gg" data-g="timer25"></i>',      false],
    ['EXPOSURE',   '<i class="gg" data-g="plusminus25"></i>',  false],
    ['ASPECT',     '<span class="aspect"><i class="gg" data-g="viewfinder30"></i><span class="ratio">4:3</span></span>', false],
    ['NIGHT MODE', '<span class="moonwrap"><i class="gg" data-g="moon30"></i></span>', false],
    ['SHOTS',      '<span class="tx yl">10</span>',            true],
    ['EVERY',      '<span class="tx yl">3s</span>',            true],
    ['AF AUTO',    '<i class="gg" data-g="lockopen25"></i>',   true]
  ];
  // v-actual: HOME reemplazo a ROLE — casita minimalista custom (misma geometria
  // que MiniHouseGlyph de la app) con el lavado rojizo sutil sobre base negra.
  const HOUSE_SVG = '<svg viewBox="0 0 23 21" style="width:19px;height:17.6px" fill="none" stroke-linecap="round" stroke-linejoin="round"><defs><linearGradient id="hg" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#fff"/><stop offset="1" stop-color="#ffd2cc"/></linearGradient></defs><path d="M.46 9.66 11.5.42l11.04 9.24M3.22 8.4v12.18h16.56V8.4" stroke="url(#hg)" stroke-width="1.45"/></svg>';
  const LOCK = '<span class="lk"><i class="gg" data-g="lockfill12" style="width:7.5px;height:8.7px"></i></span>';
  const circ = (lb, ic, iv) =>
    '<div class="dcirc' + (iv ? ' iv' : '') + '"><span class="cc">' + ic + LOCK +
    '</span><span class="lb">' + lb + '</span></div>';
  phones.forEach(p => {
    const d = document.createElement('div');
    d.className = 'pdrawer';
    d.innerHTML =
      '<div class="dgrid">' + DRAWER_ITEMS.map(i => circ(...i)).join('') + '</div>' +
      '<div class="drow">' +
        '<div class="dcirc home"><span class="cc">' + HOUSE_SVG + LOCK + '</span><span class="lb">HOME</span></div>' +
      '</div>' +
      '<a class="dcta" href="#get"><i class="gg" data-g="lockfill12" style="width:8.6px;height:10px"></i>Download the app to unlock</a>';
    $('.screen', p.root).appendChild(d);
    paintGlyphs(d);
    p.drawer = d;
    const btn = $('[data-ctl="drawer"]', p.root);
    btn.addEventListener('click', e => {
      e.stopPropagation();
      const open = !d.classList.contains('open');
      d.classList.toggle('open', open);
      btn.classList.toggle('on', open);
      btn.setAttribute('aria-expanded', open);
    });
    d.addEventListener('click', e => {
      const c = e.target.closest('.dcirc');
      if (!c) return;
      // pop + destello del CTA: se mira, se usa en la app
      const cta = $('.dcta', d);
      cta.animate?.([{ transform: 'scale(1)' }, { transform: 'scale(1.06)' }, { transform: 'scale(1)' }], { duration: 260, easing: 'ease-out' });
    });
  });
  document.addEventListener('pointerdown', e => {
    phones.forEach(p => {
      if (p.drawer.classList.contains('open') && !e.target.closest('.pdrawer,[data-ctl="drawer"]')) {
        p.drawer.classList.remove('open');
        const b = $('[data-ctl="drawer"]', p.root);
        b.classList.remove('on'); b.setAttribute('aria-expanded', 'false');
      }
    });
  });
  $$('[data-ctl="gallery"]').forEach(b => b.addEventListener('click', () => {
    $$('.gallery').forEach(g => { g.classList.remove('pop'); void g.offsetWidth; g.classList.add('pop'); });
  }));

  // los SF Symbols de la barra superior, la galeria y el flip (el drawer ya se pinto al construirse)
  paintGlyphs();

  /* 3s timer — countdown renders on BOTH screens via shared state (like snapshots) */
  function timedCapture() {
    if (state.countdown !== null || state.mode !== 'photo') return;
    let n = 3;
    state.countdown = n;
    const step = () => {
      phones.forEach(p => { p.cd.style.display = 'flex'; p.cd.textContent = n; });
      if (n === 0) {
        phones.forEach(p => p.cd.style.display = 'none');
        state.countdown = null;
        capturePhoto();
        return;
      }
      n--; setTimeout(step, 1000);
    };
    step();
  }

  /* demo shortcut chips */
  $$('[data-demo]').forEach(b => b.addEventListener('click', () => {
    const a = b.dataset.demo;
    if (a === 'zoomin')  setZoom(state.zoom + .5);
    if (a === 'zoomout') setZoom(state.zoom - .5);
    if (a === 'shoot')   fireShutter();
    if (a === 'timer')   timedCapture();
    if (a === 'burst')   { setMode('interval'); if (!burstOn) setTimeout(toggleDemoBurst, 350); }
  }));

  /* teclado y rueda: en LOS DOS visores (ninguna pantalla es "la de mirar") */
  $$('[data-tapfocus]').forEach(vf => {
    vf.addEventListener('keydown', e => {
      if (e.key === 'ArrowUp')   { e.preventDefault(); setZoom(state.zoom + .25); }
      if (e.key === 'ArrowDown') { e.preventDefault(); setZoom(state.zoom - .25); }
      if (e.key === ' ' || e.key === 'Enter') { e.preventDefault(); fireShutter(); }
    });
    vf.addEventListener('wheel', e => { e.preventDefault(); setZoom(state.zoom - Math.sign(e.deltaY) * .12); }, { passive: false });
  });
  addEventListener('keydown', e => {
    if (e.target.closest('input,textarea,dialog')) return;
    if (e.key === ' ' && $('#demo').getBoundingClientRect().top < innerHeight * .5 && $('#demo').getBoundingClientRect().bottom > 0) {
      e.preventDefault(); fireShutter();
    }
  });

  /* ═════ scene renderer — one world, two screens ═════ */
  function drawScene(p, t, lagged) {
    const { ctx, canvas } = p, W = canvas.width, H = canvas.height;
    const tt = lagged ? t - .012 : t;                       // the honest 12ms
    const night = state.night, ev = state.ev;
    ctx.save();
    // zoom about the center
    ctx.translate(W / 2, H / 2); ctx.scale(state.zoom, state.zoom); ctx.translate(-W / 2, -H / 2);
    if (state.front) ctx.transform(-1, 0, 0, 1, W, 0);      // flipped camera = mirrored world
    // sky
    const sky = ctx.createLinearGradient(0, 0, 0, H);
    if (night) { sky.addColorStop(0, '#050816'); sky.addColorStop(.6, '#0b1230'); sky.addColorStop(1, '#131a38'); }
    else { sky.addColorStop(0, '#1a2440'); sky.addColorStop(.45, '#4a3560'); sky.addColorStop(.78, '#c96f3a'); sky.addColorStop(1, '#f2a541'); }
    ctx.fillStyle = sky; ctx.fillRect(-W, -H, W * 3, H * 3);
    // stars at night
    if (night) { ctx.fillStyle = 'rgba(255,255,255,.8)';
      for (let i = 0; i < 60; i++) { const sx = (i * 137.5) % W, sy = (i * 89.7) % (H * .5);
        ctx.globalAlpha = .3 + .7 * Math.abs(Math.sin(tt * 2 + i)); ctx.fillRect(sx, sy, 1.4, 1.4); }
      ctx.globalAlpha = 1; }
    // sun / moon
    const sunY = H * .34 + Math.sin(tt * .21) * 6;
    ctx.beginPath(); ctx.arc(W * .68, sunY, night ? 20 : 34, 0, 7);
    ctx.fillStyle = night ? '#e8e3d0' : '#ffd27a';
    ctx.shadowColor = night ? '#e8e3d0' : '#f59e0b'; ctx.shadowBlur = night ? 22 : 48;
    ctx.fill(); ctx.shadowBlur = 0;
    // mountain layers w/ drift
    const layer = (base, amp, speed, col) => {
      ctx.beginPath(); ctx.moveTo(-W, H);
      for (let x = -W; x <= W * 2; x += 12) {
        const y = base + Math.sin((x * .011) + tt * speed) * amp + Math.sin((x * .033) + tt * speed * .6) * amp * .4;
        ctx.lineTo(x, y);
      }
      ctx.lineTo(W * 2, H * 2); ctx.closePath(); ctx.fillStyle = col; ctx.fill();
    };
    if (night) { layer(H * .52, 26, .18, '#0c1226'); layer(H * .62, 34, .26, '#080d1d'); layer(H * .74, 24, .38, '#04070f'); }
    else { layer(H * .52, 26, .18, '#5a3550'); layer(H * .62, 34, .26, '#38243f'); layer(H * .74, 24, .38, '#1d1226'); }
    // water shimmer
    const wg = ctx.createLinearGradient(0, H * .8, 0, H);
    wg.addColorStop(0, night ? 'rgba(120,140,200,.16)' : 'rgba(245,158,11,.24)'); wg.addColorStop(1, 'rgba(0,0,0,.5)');
    ctx.fillStyle = wg; ctx.fillRect(-W, H * .8, W * 3, H * .2);
    for (let i = 0; i < 14; i++) {
      const y = H * .82 + i * (H * .012);
      const w = 30 + 60 * Math.abs(Math.sin(tt * 1.1 + i));
      ctx.fillStyle = night ? 'rgba(190,200,255,.10)' : 'rgba(255,205,120,.16)';
      ctx.fillRect(W * .68 - w / 2 + Math.sin(tt + i) * 8, y, w, 1.6);
    }
    ctx.restore();
    // EV + night exposure
    const bright = ev * .28 + (night ? -.06 : 0);
    if (bright > 0) { ctx.fillStyle = 'rgba(255,255,255,' + Math.min(.5, bright) + ')'; ctx.fillRect(0, 0, W, H); }
    if (bright < 0) { ctx.fillStyle = 'rgba(0,0,0,' + Math.min(.6, -bright) + ')'; ctx.fillRect(0, 0, W, H); }
    // flash pop (drawn in-world so the gallery snapshot catches it)
    if (flashT && t - flashT < .18) { ctx.fillStyle = 'rgba(255,255,255,' + (0.7 * (1 - (t - flashT) / .18)) + ')'; ctx.fillRect(0, 0, W, H); }
  }

  /* EV drag: arrastre vertical sobre CUALQUIERA de los dos visores, despues de enfocar */
  let evDrag = null;
  $$('[data-tapfocus]').forEach(vf => {
    vf.addEventListener('pointerdown', e => { evDrag = { y: e.clientY, ev: state.ev }; });
    vf.addEventListener('pointermove', e => {
      if (!evDrag || e.buttons !== 1) return;
      const dy = e.clientY - evDrag.y;
      if (Math.abs(dy) > 14) state.ev = Math.max(-2, Math.min(2, evDrag.ev - dy / 130));
    });
    vf.addEventListener('pointerup', () => evDrag = null);
  });

  /* render loop (pauses off-screen; respects reduced motion with a static frame) */
  let running = false;
  const demoIO = new IntersectionObserver(es => es.forEach(e => {
    running = e.isIntersecting;
    if (running && !reduced) loop();
    if (running && reduced) { state.t = 4; phones.forEach((p, i) => drawScene(p, state.t, i === 0)); }
  }), { threshold: .05 });
  demoIO.observe($('#demo'));
  function loop() {
    if (!running || reduced) return;
    state.t = performance.now() / 1000;
    phones.forEach((p, i) => drawScene(p, state.t, i === 0));
    requestAnimationFrame(loop);
  }

  /* anillos nativos por modo (replica 1:1): slo-mo dientes densos, time-lapse reloj de 60 */
  phones.forEach(p => {
    const teeth = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
    teeth.setAttribute('viewBox', '0 0 82 82'); teeth.setAttribute('class', 'ringsvg rs');
    teeth.innerHTML = '<circle cx="41" cy="41" r="35.5" fill="none" stroke="rgba(255,255,255,.92)" stroke-width="6" stroke-dasharray="1.25 1.55"/>';
    const clock = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
    clock.setAttribute('viewBox', '0 0 82 82'); clock.setAttribute('class', 'ringsvg rt');
    let ticks = '';
    for (let i = 0; i < 60; i++) {
      const major = i % 10 === 0;
      const h = major ? 6.5 : 2.5, w = major ? 1.9 : 1.4;
      ticks += '<rect x="' + (41 - w / 2) + '" y="1.5" width="' + w + '" height="' + h + '" rx="' + (w / 2) + '" fill="rgba(255,255,255,' + (major ? .95 : .85) + ')" transform="rotate(' + (i * 6) + ' 41 41)"/>';
    }
    clock.innerHTML = ticks;
    p.shutter.appendChild(teeth); p.shutter.appendChild(clock);
  });

  /* flags de verificacion (headless screenshots): ?drawer abre los cajones, ?interval cambia el modo */
  if (location.search.includes('interval')) setMode('interval');
  if (location.search.includes('drawer')) phones.forEach(p => {
    p.drawer.classList.add('open');
    if (location.search.includes('interval')) p.drawer.classList.add('interval');
  });

  /* boot */
  setZoom(1); phones.forEach(p => carouselLayout(p, 0, false));
  // FPS tag heartbeat (cosmetic but honest about being a simulation)
  setInterval(() => {
    const f = 29 + Math.round(Math.random() * 2), ms = 11 + Math.round(Math.random() * 4);
    $$('.fpsTag').forEach(t => t.textContent = f + ' FPS · ' + ms + ' MS');
  }, 1400);
})();
